fun interface Validator<in T> { fun validate(value: T): List<String> }   // in T = contravariant
fun <T> and(a: Validator<T>, b: Validator<T>) = Validator<T> { a.validate(it) + b.validate(it) }

val port = Validator<Config> { c ->
    if (c.port in 1..65535) emptyList() else listOf("port out of range")
}
val config = and(port, Validator { c -> if (c.host.isNotBlank()) emptyList() else listOf("host blank") })
